async function ready(page){await page.waitForFunction(()=>document.querySelector('#status').dataset.guardian,null,{timeout:15000});const game=page.frames().find(f=>f!==page.mainFrame());assert.ok(game);assert.deepEqual((await game.evaluate(()=>window.MaxNativeArt.load())).failed,[]);assert.equal(await game.evaluate(()=>typeof window.__cairnCombat),'object');return game;}
async function focus(game){await game.evaluate(()=>{window.focus();const c=window.__cairnCombat.canvas;c.tabIndex=-1;c.focus({preventScroll:true});});}
async function press(page,game,key,kind){await focus(game);if(kind)await game.evaluate(kind=>window.__cairnCombat.forgetBody(kind),kind);await page.keyboard.press(key);}
async function down(page,game,key,kind){await focus(game);if(kind)await game.evaluate(kind=>window.__cairnCombat.forgetBody(kind),kind);await page.keyboard.down(key);}
function nativeCell(body){assert.ok(body);assert.equal(body.rect.length,8);assert.deepEqual([body.rect[2],body.rect[3],body.rect[6],body.rect[7]],[32,32,32,32]);assert.ok(body.rect.every(Number.isInteger));if(body.cell&&body.q){const face=body.name.startsWith('brace')?body.q.braceFace:body.name.startsWith('ridge')?body.q.ridgeFace:body.name.includes('sweep')||body.name.includes('knuckle')?body.q.primaryFace:body.q.stoneVX<0?-1:1;assert.equal(body.cell.face,face,'Native cell retains accepted facing');}}
async function body(game,kind){const names={primary0:['sweep-ready','sweep'],primary1:['reverse-sweep-ready','reverse-sweep'],primary2:['knuckle-ready','knuckle'],brace:['brace'],ridge:['ridge-ready'],stone:['loose-stone']};await game.waitForFunction(({kind,names})=>{var b=window.__cairnCombat.state.bodies[kind];return b&&b.cell&&names.includes(b.name);},{kind,names:names[kind]},{timeout:2000});const rendered=(await state(game)).bodies[kind];nativeCell(rendered);assert.equal(rendered.source,rendered.cell.sheet+'.png');assert.equal(rendered.rect[0],rendered.cell.column*32);assert.equal(rendered.rect[1],rendered.cell.row*32);return rendered;}
async function shot(page,engine,name){const game=page.frames().find(f=>f!==page.mainFrame());assert.equal(await game.evaluate(()=>!!(window.MaxRunResults&&window.MaxRunResults.isOpen())),false);await page.locator('iframe').screenshot({path:path.join(output,engine+'-'+name+'.png')});}
